cd "/c/Users/guitest/AppData/Local/Temp/claude/C--src-JusPrin/5000aebe-8930-435c-b917-8a2339851977/scratchpad/canvas-updates" && cat > splice.js <<'EOF'
const fs=require('fs');
const f='project/prefs-window.dc.html';
let s=fs.readFileSync(f,'utf8');
const start=s.indexOf('<sc-if value="{{isUpdates}}"');
const endMark='</section>\n</sc-if>';
const end=s.indexOf(endMark,start)+endMark.length;
if(start<0||end<endMark.length) throw new Error('markers');
s=s.slice(0,start)+fs.readFileSync('updates-section.html','utf8').trimEnd()+s.slice(end);
function rep(a,b){ if(s.split(a).length!==2) throw new Error('not unique: '+a.slice(0,60)); s=s.replace(a,b); }
rep('<sc-if value="{{updateAvailable}}" hint-placeholder-val="{{ false }}"><span aria-label="Update available"','<sc-if value="{{up.dot}}" hint-placeholder-val="{{ false }}"><span aria-label="Update available"');
rep('"update":{"editor":"enum","options":["current","available"],"default":"current"}','"update":{"editor":"enum","options":["current","checking","failed","available","downloading","ready","downloadFailed","store"],"default":"current"}');
rep("      updateAvailable: update === 'available', upToDate: update !== 'available',\n",
"      up: {\n        current: update === 'current', checking: update === 'checking', failed: update === 'failed',\n        available: update === 'available', downloading: update === 'downloading', ready: update === 'ready',\n        downloadFailed: update === 'downloadFailed', store: update === 'store',\n        dot: update === 'available' || update === 'downloading' || update === 'ready',\n        selfChecks: update !== 'store'\n      },\n");
rep("      checkNow: set({ update: 'available' }), goAgent: set({ section: 'agent' })",
"      checkNow: () => { this.setState({ update: 'checking' }); setTimeout(() => this.setState({ update: 'available' }), 1200); },\n      download: () => { this.setState({ update: 'downloading' }); setTimeout(() => this.setState({ update: 'ready' }), 1600); },\n      cancel: set({ update: 'available' }), skip: set({ update: 'current' }),\n      goAgent: set({ section: 'agent' })");
if (/updateAvailable|upToDate/.test(s)) throw new Error('leftover');
fs.writeFileSync(f,s);
// wrappers
const tpl=fs.readFileSync('project/prefs-updates-available.dc.html','utf8');
const boards=[
 ['prefs-updates.dc.html','Updates',null,640],
 ['prefs-updates-checking.dc.html','Updates · checking','checking',640],
 ['prefs-updates-failed.dc.html','Updates · couldn’t check','failed',660],
 ['prefs-updates-available.dc.html','Updates · new version available','available',860],
 ['prefs-updates-downloading.dc.html','Updates · downloading','downloading',660],
 ['prefs-updates-ready.dc.html','Updates · ready to install','ready',680],
 ['prefs-updates-download-failed.dc.html','Updates · download didn’t finish','downloadFailed',680],
 ['prefs-updates-store.dc.html','Updates · Microsoft Store install','store',560],
 ['prefs-updates-available-dark.dc.html','Updates · new version available · dark','available',860,'dark'],
];
for (const [file,title,state,h,theme] of boards) {
  let w=tpl.replace(/<title>[^<]*<\/title>/,'<title>Preferences · '+title+'</title>')
    .replace(/<div style="width:800px;height:\d+px">/,'<div style="width:800px;height:'+h+'px">')
    .replace(/<dc-import [^>]*><\/dc-import>/,'<dc-import name="prefs-window" section="updates"'+(state?' update="'+state+'"':'')+(theme?' theme="'+theme+'"':'')+' window-height="'+h+'" hint-size="800px,'+h+'px"></dc-import>')
    .replace(/"\$preview":\{"width":800,"height":\d+\}/,'"$preview":{"width":800,"height":'+h+'}');
  fs.writeFileSync('project/'+file,w);
}
// index
const c=JSON.parse(fs.readFileSync('project/canvas.json','utf8'));
c.boards['prefs-updates-available.dc.html'].h=860;
const rowTop=11324; let x=0;
for (const [file,title,state,h] of boards.slice(1)) {
  if (file==='prefs-updates-available.dc.html') { c.boards[file].x=x; c.boards[file].y=rowTop; c.boards[file].title=title; }
  else { c.boards[file]={x,y:rowTop,w:800,h,title,page:'agent-prefs'}; c.order.push(file); }
  x+=880;
}
c.notes.prefUpd1={x:0,y:11252,text:'Updates · from “Check now” to “Restart and install”',kind:'title1',size:40,maxW:x-80,page:'agent-prefs'};
c.notes.prefUpd2={x:x,y:11324,w:420,maxH:760,page:'agent-prefs',text:
'Updates · proposed 2026-10-22. JusPrin’s own check replaces OrcaSlicer’s update window, which JusPrin does not show.\n\n'+
'Where releases come from: the release list of TheSpaghettiDetective/JusPrin on GitHub. Stable releases only. A test build is told about newer test builds. Nightly builds are never offered.\n\n'+
'When: at start if the last check is over a day old, once a day while JusPrin stays open, and on Check now.\n\n'+
'Where it shows: only here, plus the dot on Updates. Nothing pops up, and nothing appears in a project or in chat. The Agent never downloads or installs.\n\n'+
'Download and install: JusPrin downloads the file for this computer (Windows installer, macOS disk image, AppImage) and checks it against the checksum GitHub publishes. Restart and install saves projects, quits and runs the installer. On macOS the last step opens the disk image instead. A portable or Flatpak copy gets “Download from GitHub” instead of installing.\n\n'+
'Skip this version hides it until a newer one comes out. Offline or a failed check is quiet: the card says so and JusPrin tries again later.'};
fs.writeFileSync('project/canvas.json',JSON.stringify(c,null,2));
console.log('ok', Object.keys(c.boards).filter(k=>k.startsWith('prefs-updates')));
EOF
node splice.js && grep -c "up\.\|stable" project/prefs-window.dc.html; grep -n "Stable releases" project/prefs-window.dc.html

