const root = 'C:/src/JusPrin/.claude/worktrees/prefs-update-check/src/slic3r/GUI/JusPrin/AgentUI/src/';
function rep(f, a, b) {
  const p = root + f;
  let s = fs.readFileSync(p, 'utf8');
  const crlf = s.includes('\r\n');
  if (crlf) s = s.replace(/\r\n/g, '\n');
  if (s.split(a).length !== 2) throw new Error(f + ': ' + a.slice(0, 70));
  s = s.replace(a, () => b);
  if (crlf) s = s.replace(/\n/g, '\r\n');
  fs.writeFileSync(p, s);
}
