// A stand-in for GET /repos/TheSpaghettiDetective/JusPrin/releases.
// Usage: node fake-github.js <port> <new|current|garbage|slow|down> <log file>
// Every request's method, path and headers are appended to the log file.
// Opening http://127.0.0.1:<port>/__mode/<mode> in a browser switches what it
// answers; "down" answers 503, as an unreachable GitHub would fail.
const http = require('http');
const fs = require('fs');
const [port, startMode, logFile] = process.argv.slice(2);
let mode = startMode;

const release = (tag, extra = {}) => ({
  tag_name: tag,
  draft: false,
  prerelease: false,
  html_url: `https://github.com/TheSpaghettiDetective/JusPrin/releases/tag/${tag}`,
  published_at: '2026-11-02T10:00:00Z',
  body: null,
  ...extra,
});
const today = [
  release('nightly-builds', { prerelease: true }),
  release('jusprin/v1.4.0', { body: 'JusPrin 1.4.0' }),
  release('v1.3.0'),
];
const responses = {
  current: JSON.stringify(today),
  new: JSON.stringify([
    release('v2.1.0', {
      body: '## What\'s new\n\n- Plates slice on their own once the project is quiet\n- Preferences has its own window\n\n## Fixes\n\n- OrcaSlicer\'s update window no longer opens',
    }),
    release('v2.2.0-beta1', { prerelease: true }),
    ...today,
  ]),
  garbage: '<html><body>Sign in to the Wi-Fi</body></html>',
};

http.createServer((req, res) => {
  const switchTo = req.url.match(/^\/__mode\/(\w+)/);
  if (switchTo) {
    mode = switchTo[1];
    res.writeHead(200, { 'Content-Type': 'text/plain' });
    res.end(`The fake GitHub now answers: ${mode}\n`);
    return;
  }
  fs.appendFileSync(logFile, JSON.stringify({ at: new Date().toISOString(), mode, method: req.method, url: req.url, headers: req.headers }) + '\n');
  if (mode === 'down') {
    res.writeHead(503, { 'Content-Type': 'text/plain' });
    res.end('Service unavailable');
    return;
  }
  const delay = mode === 'slow' ? 6000 : 0;
  setTimeout(() => {
    res.writeHead(200, { 'Content-Type': mode === 'garbage' ? 'text/html' : 'application/json' });
    res.end(responses[mode === 'slow' ? 'current' : mode]);
  }, delay);
}).listen(Number(port), '127.0.0.1', () => console.log(`fake GitHub (${mode}) on ${port}`));

